formulas.expression:
IF(
    AND(
        OR(
            {!$Record.dn_Financial_Class__c} = "Aetna"

        ),
        TEXT({!$Record.dn_PROVIDER_GROUPING__c}) = "MD"
    ),
    "Valid",
    "Invalid"
)

IF(
    AND(
        NOT(ISBLANK({!$Record.dn_Patient_Account__r.dn_Name__c})), 

        /* First character must be 'A' */
        MID(UPPER({!$Record.dn_Patient_Account__r.dn_Name__c}), 1, 1) = "A", 

        /* Second character must be between 'A' and 'N' */
        MID(UPPER({!$Record.dn_Patient_Account__r.dn_Name__c}), 2, 1) >= "A", 
        MID(UPPER({!$Record.dn_Patient_Account__r.dn_Name__c}), 2, 1) <= "N", 

        /* Third character must be between 'A' and 'D' */
        MID(UPPER({!$Record.dn_Patient_Account__r.dn_Name__c}), 3, 1) >= "A", 
        MID(UPPER({!$Record.dn_Patient_Account__r.dn_Name__c}), 3, 1) <= "D"
    ), 
    "Valid", 
    "Invalid"
)

IF(
    AND(
        NOT(ISBLANK({!$Record.dn_Patient_Account__r.dn_Name__c})), 

        OR(
            /* If first character is A or B, it's valid */
            MID(UPPER({!$Record.dn_Patient_Account__r.dn_Name__c}), 1, 1) = "A",

            /* If first character is B, apply additional checks */
            AND(
                MID(UPPER({!$Record.dn_Patient_Account__r.dn_Name__c}), 1, 1) = "B",
                MID(UPPER({!$Record.dn_Patient_Account__r.dn_Name__c}), 2, 1) >= "N",
                MID(UPPER({!$Record.dn_Patient_Account__r.dn_Name__c}), 2, 1) <= "R",
                MID(UPPER({!$Record.dn_Patient_Account__r.dn_Name__c}), 3, 1) >= "E",
                MID(UPPER({!$Record.dn_Patient_Account__r.dn_Name__c}), 3, 1) <= "I"
            )
        )
    ),
    "Valid",
    "Invalid"
)

IF(
    AND(
        NOT(ISBLANK({!$Record.dn_Patient_Account__r.dn_Name__c})), 

        OR(
            /* If first character is B or C, it's automatically valid */
            MID(UPPER({!$Record.dn_Patient_Account__r.dn_Name__c}), 1, 1) = "B",

            /* If first character is C, apply additional checks */
            AND(
                MID(UPPER({!$Record.dn_Patient_Account__r.dn_Name__c}), 1, 1) = "C",
                MID(UPPER({!$Record.dn_Patient_Account__r.dn_Name__c}), 2, 1) >= "A",
                MID(UPPER({!$Record.dn_Patient_Account__r.dn_Name__c}), 2, 1) <= "L"
            )
        )
    ),
    "Valid",
    "Invalid"
)

IF(
    AND(
        NOT(ISBLANK({!$Record.dn_Patient_Account__r.dn_Name__c})), 

        OR(
            /* If first character is C or D, it's automatically valid */
            MID(UPPER({!$Record.dn_Patient_Account__r.dn_Name__c}), 1, 1) = "C",

            /* If first character is D, apply additional checks */
            AND(
                MID(UPPER({!$Record.dn_Patient_Account__r.dn_Name__c}), 1, 1) = "D",
                MID(UPPER({!$Record.dn_Patient_Account__r.dn_Name__c}), 2, 1) >= "A",
                MID(UPPER({!$Record.dn_Patient_Account__r.dn_Name__c}), 2, 1) <= "A"
            )
        )
    ),
    "Valid",
    "Invalid"
)

IF(
    AND(
      NOT(ISBLANK({!$Record.dn_Patient_Account__r.dn_Name__c})), 

        OR(
            /* If first character is D or E, it's automatically valid */
            MID(UPPER({!$Record.dn_Patient_Account__r.dn_Name__c}), 1, 1) = "D",

            /* If first character is E, apply additional checks */
            AND(
                MID(UPPER({!$Record.dn_Patient_Account__r.dn_Name__c}), 1, 1) = "E",
                MID(UPPER({!$Record.dn_Patient_Account__r.dn_Name__c}), 2, 1) >= "A",
                MID(UPPER({!$Record.dn_Patient_Account__r.dn_Name__c}), 2, 1) <= "M"
            )
        )
    ),
    "Valid",
    "Invalid"
)

IF(
    AND(
       NOT(ISBLANK({!$Record.dn_Patient_Account__r.dn_Name__c})), 

        OR(
            /* If first character is F or G, it's automatically valid */
            MID(UPPER({!$Record.dn_Patient_Account__r.dn_Name__c}), 1, 1) = "F",
            MID(UPPER({!$Record.dn_Patient_Account__r.dn_Name__c}), 1, 1) = "G",

            /* If first character is E, apply additional check */
            AND(
                MID(UPPER({!$Record.dn_Patient_Account__r.dn_Name__c}), 1, 1) = "E",
                MID(UPPER({!$Record.dn_Patient_Account__r.dn_Name__c}), 2, 1) >= "N"
            )
        )
    ),
    "Valid",
    "Invalid"
)

IF(
    AND(
        NOT(ISBLANK({!$Record.dn_Patient_Account__r.dn_Name__c})), 

        OR(
            /* If first character is H or I, it's valid */
            MID(UPPER({!$Record.dn_Patient_Account__r.dn_Name__c}), 1, 1) = "H",
             MID(UPPER({!$Record.dn_Patient_Account__r.dn_Name__c}), 1, 1) = "I",

            /* If first character is J, apply additional checks */
            AND(
                MID(UPPER({!$Record.dn_Patient_Account__r.dn_Name__c}), 1, 1) = "J",
                MID(UPPER({!$Record.dn_Patient_Account__r.dn_Name__c}), 2, 1) >= "A",
                MID(UPPER({!$Record.dn_Patient_Account__r.dn_Name__c}), 2, 1) <= "E",
                MID(UPPER({!$Record.dn_Patient_Account__r.dn_Name__c}), 3, 1) >= "A",
                MID(UPPER({!$Record.dn_Patient_Account__r.dn_Name__c}), 3, 1) <= "F"
            )
        )
    ),
    "Valid",
    "Invalid"
)

IF(
    AND(
       NOT(ISBLANK({!$Record.dn_Patient_Account__r.dn_Name__c})), 

        OR(
            /* First character is J (No second/third char check) */
            MID(UPPER({!$Record.dn_Patient_Account__r.dn_Name__c}), 1, 1) = "J",

            /* First character is K and second character is between A to H */
            AND(
                MID(UPPER({!$Record.dn_Patient_Account__r.dn_Name__c}), 1, 1) = "K",
                MID(UPPER({!$Record.dn_Patient_Account__r.dn_Name__c}), 2, 1) >= "A",
                MID(UPPER({!$Record.dn_Patient_Account__r.dn_Name__c}), 2, 1) <= "H"
            )
        )
    ),
    "Valid",
    "Invalid"
)

IF(
    AND(
        NOT(ISBLANK({!$Record.dn_Patient_Account__r.dn_Name__c})), 

        OR(
            /* First character is K (No second/third char check) */
            MID(UPPER({!$Record.dn_Patient_Account__r.dn_Name__c}), 1, 1) = "K",

            /* First character is L and second character is between A to I */
            AND(
                MID(UPPER({!$Record.dn_Patient_Account__r.dn_Name__c}), 1, 1) = "L",
                MID(UPPER({!$Record.dn_Patient_Account__r.dn_Name__c}), 2, 1) >= "A",
                MID(UPPER({!$Record.dn_Patient_Account__r.dn_Name__c}), 2, 1) <= "I"
            )
        )
    ),
    "Valid",
    "Invalid"
)

IF(
    AND(
      NOT(ISBLANK({!$Record.dn_Patient_Account__r.dn_Name__c})), 

        OR(
            /* First character is L (No second/third char check) */
            MID(UPPER({!$Record.dn_Patient_Account__r.dn_Name__c}), 1, 1) = "L",

            /* First character is M, second character must be A, third character must be A to R */
            AND(
                MID(UPPER({!$Record.dn_Patient_Account__r.dn_Name__c}), 1, 1) = "M",
                MID(UPPER({!$Record.dn_Patient_Account__r.dn_Name__c}), 2, 1) = "A",
                MID(UPPER({!$Record.dn_Patient_Account__r.dn_Name__c}), 3, 1) >= "A",
                MID(UPPER({!$Record.dn_Patient_Account__r.dn_Name__c}), 3, 1) <= "R"
            )
        )
    ),
    "Valid",
    "Invalid"
)

IF(
    AND(
        NOT(ISBLANK({!$Record.dn_Patient_Account__r.dn_Name__c})), 

        /* First character must be 'M' */
        MID(UPPER({!$Record.dn_Patient_Account__r.dn_Name__c}), 1, 1) = "M",

        /* Second character must be between 'A' and 'I' */
        MID(UPPER({!$Record.dn_Patient_Account__r.dn_Name__c}), 2, 1) >= "A",
        MID(UPPER({!$Record.dn_Patient_Account__r.dn_Name__c}), 2, 1) <= "I"
    ),
    "Valid",
    "Invalid"
)

IF(
    AND(
        NOT(ISBLANK({!$Record.dn_Patient_Account__r.dn_Name__c})), 

        OR(
            /* If first character is H or I, it's valid */
            MID(UPPER({!$Record.dn_Patient_Account__r.dn_Name__c}), 1, 1) = "M",
             MID(UPPER({!$Record.dn_Patient_Account__r.dn_Name__c}), 1, 1) = "O",

            /* If first character is J, apply additional checks */
            AND(
                MID(UPPER({!$Record.dn_Patient_Account__r.dn_Name__c}), 1, 1) = "P",
                MID(UPPER({!$Record.dn_Patient_Account__r.dn_Name__c}), 2, 1) = "A",
                MID(UPPER({!$Record.dn_Patient_Account__r.dn_Name__c}), 3, 1) >= "A",
                MID(UPPER({!$Record.dn_Patient_Account__r.dn_Name__c}), 3, 1) <= "T"

            )
        )
    ),
    "Valid",
    "Invalid"
)

IF(
  AND(
    NOT(ISBLANK({!$Record.dn_Patient_Account__r.dn_Name__c})),

    /* First character must be A */
    MID(UPPER({!$Record.dn_Patient_Account__r.dn_Name__c}), 1, 1) = "A",

    /* Second character: A–L */
    MID(UPPER({!$Record.dn_Patient_Account__r.dn_Name__c}), 2, 1) >= "A",
    MID(UPPER({!$Record.dn_Patient_Account__r.dn_Name__c}), 2, 1) <= "L",

    /* Third character: A–Y */
    MID(UPPER({!$Record.dn_Patient_Account__r.dn_Name__c}), 3, 1) >= "A",
    MID(UPPER({!$Record.dn_Patient_Account__r.dn_Name__c}), 3, 1) <= "Y",

    /* Fourth character: A–S */
    MID(UPPER({!$Record.dn_Patient_Account__r.dn_Name__c}), 4, 1) >= "A",
    MID(UPPER({!$Record.dn_Patient_Account__r.dn_Name__c}), 4, 1) <= "S",

    /* Fifth character: A–S */
    MID(UPPER({!$Record.dn_Patient_Account__r.dn_Name__c}), 5, 1) >= "A",
    MID(UPPER({!$Record.dn_Patient_Account__r.dn_Name__c}), 5, 1) <= "S",

    /* Sixth character: A */
    MID(UPPER({!$Record.dn_Patient_Account__r.dn_Name__c}), 6, 1) = "A",

    /* Seventh character: must be a space */
    MID({!$Record.dn_Patient_Account__r.dn_Name__c}, 7, 1) = " ",

    /* Eighth character: A–C */
    MID(UPPER({!$Record.dn_Patient_Account__r.dn_Name__c}), 8, 1) >= "A",
    MID(UPPER({!$Record.dn_Patient_Account__r.dn_Name__c}), 8, 1) <= "C"
  ),
  "Valid",
  "Invalid"
)

IF(
  AND(
    NOT(ISBLANK({!$Record.dn_Patient_Account__r.dn_Name__c})),

    /* 1st character: must be A */
    MID(UPPER({!$Record.dn_Patient_Account__r.dn_Name__c}), 1, 1) = "A",

    /* 2nd character: A–N */
    MID(UPPER({!$Record.dn_Patient_Account__r.dn_Name__c}), 2, 1) >= "A",
    MID(UPPER({!$Record.dn_Patient_Account__r.dn_Name__c}), 2, 1) <= "N",

    /* 3rd character: A–T */
    MID(UPPER({!$Record.dn_Patient_Account__r.dn_Name__c}), 3, 1) >= "A",
    MID(UPPER({!$Record.dn_Patient_Account__r.dn_Name__c}), 3, 1) <= "T",

    /* 4th character: A–O */
    MID(UPPER({!$Record.dn_Patient_Account__r.dn_Name__c}), 4, 1) >= "A",
    MID(UPPER({!$Record.dn_Patient_Account__r.dn_Name__c}), 4, 1) <= "O",

    /* 5th character: A–N */
    MID(UPPER({!$Record.dn_Patient_Account__r.dn_Name__c}), 5, 1) >= "A",
    MID(UPPER({!$Record.dn_Patient_Account__r.dn_Name__c}), 5, 1) <= "N",

    /* 6th character: A–I */
    MID(UPPER({!$Record.dn_Patient_Account__r.dn_Name__c}), 6, 1) >= "A",
    MID(UPPER({!$Record.dn_Patient_Account__r.dn_Name__c}), 6, 1) <= "I",

    /* 7th character: A–N */
    MID(UPPER({!$Record.dn_Patient_Account__r.dn_Name__c}), 7, 1) >= "A",
    MID(UPPER({!$Record.dn_Patient_Account__r.dn_Name__c}), 7, 1) <= "N"
  ),
  "Valid",
  "Invalid"
)

IF(
  AND(
    NOT(ISBLANK({!$Record.dn_Patient_Account__r.dn_Name__c})),

    OR(
      /* If first character is A, it's valid */
      MID(UPPER({!$Record.dn_Patient_Account__r.dn_Name__c}), 1, 1) = "A",

      /* If first character is B, apply checks for 2nd and 3rd letters */
      AND(
        MID(UPPER({!$Record.dn_Patient_Account__r.dn_Name__c}), 1, 1) = "B",
        MID(UPPER({!$Record.dn_Patient_Account__r.dn_Name__c}), 2, 1) >= "A",
        MID(UPPER({!$Record.dn_Patient_Account__r.dn_Name__c}), 2, 1) <= "I",
        MID(UPPER({!$Record.dn_Patient_Account__r.dn_Name__c}), 3, 1) >= "A",
        MID(UPPER({!$Record.dn_Patient_Account__r.dn_Name__c}), 3, 1) <= "L"
      )
    )
  ),
  "Valid",
  "Invalid"
)

IF(
  AND(
    NOT(ISBLANK({!$Record.dn_Patient_Account__r.dn_Name__c})),

    /* First character must be B */
    MID(UPPER({!$Record.dn_Patient_Account__r.dn_Name__c}), 1, 1) = "B",

    /* Second character between A and R */
    MID(UPPER({!$Record.dn_Patient_Account__r.dn_Name__c}), 2, 1) >= "A",
    MID(UPPER({!$Record.dn_Patient_Account__r.dn_Name__c}), 2, 1) <= "R",

    /* Third character between A and Y */
    MID(UPPER({!$Record.dn_Patient_Account__r.dn_Name__c}), 3, 1) >= "A",
    MID(UPPER({!$Record.dn_Patient_Account__r.dn_Name__c}), 3, 1) <= "Y"
  ),
  "Valid",
  "Invalid"
)

IF(
  AND(
    NOT(ISBLANK({!$Record.dn_Patient_Account__r.dn_Name__c})),

    /* 1st character: A to C */
    MID(UPPER({!$Record.dn_Patient_Account__r.dn_Name__c}), 1, 1) >= "B",
    MID(UPPER({!$Record.dn_Patient_Account__r.dn_Name__c}), 1, 1) <= "C",

    /* Proceed with deeper checks only if 1st character is C */
    OR(
      MID(UPPER({!$Record.dn_Patient_Account__r.dn_Name__c}), 1, 1) < "C",

      AND(
        MID(UPPER({!$Record.dn_Patient_Account__r.dn_Name__c}), 1, 1) = "C",

        /* 2nd character: A–H */
        MID(UPPER({!$Record.dn_Patient_Account__r.dn_Name__c}), 2, 1) >= "A",
        MID(UPPER({!$Record.dn_Patient_Account__r.dn_Name__c}), 2, 1) <= "H",

        /* 3rd character: A–R */
        MID(UPPER({!$Record.dn_Patient_Account__r.dn_Name__c}), 3, 1) >= "A",
        MID(UPPER({!$Record.dn_Patient_Account__r.dn_Name__c}), 3, 1) <= "R",

        /* 4th character: A–I */
        MID(UPPER({!$Record.dn_Patient_Account__r.dn_Name__c}), 4, 1) >= "A",
        MID(UPPER({!$Record.dn_Patient_Account__r.dn_Name__c}), 4, 1) <= "I",

        /* 5th character: A–S */
        MID(UPPER({!$Record.dn_Patient_Account__r.dn_Name__c}), 5, 1) >= "A",
        MID(UPPER({!$Record.dn_Patient_Account__r.dn_Name__c}), 5, 1) <= "S",

        /* 6th character: A–T */
        MID(UPPER({!$Record.dn_Patient_Account__r.dn_Name__c}), 6, 1) >= "A",
        MID(UPPER({!$Record.dn_Patient_Account__r.dn_Name__c}), 6, 1) <= "T",

        /* 7th character: A–I */
        MID(UPPER({!$Record.dn_Patient_Account__r.dn_Name__c}), 7, 1) >= "A",
        MID(UPPER({!$Record.dn_Patient_Account__r.dn_Name__c}), 7, 1) <= "I",

        /* 8th character: A–N */
        MID(UPPER({!$Record.dn_Patient_Account__r.dn_Name__c}), 8, 1) >= "A",
        MID(UPPER({!$Record.dn_Patient_Account__r.dn_Name__c}), 8, 1) <= "N",

        /* 9th character: A */
        MID(UPPER({!$Record.dn_Patient_Account__r.dn_Name__c}), 9, 1) = "A",

        /* 10th character: space */
        MID({!$Record.dn_Patient_Account__r.dn_Name__c}, 10, 1) = " ",

        /* 11th character: A–K */
        MID(UPPER({!$Record.dn_Patient_Account__r.dn_Name__c}), 11, 1) >= "A",
        MID(UPPER({!$Record.dn_Patient_Account__r.dn_Name__c}), 11, 1) <= "K"
      )
    )
