  "Valid",
  "Invalid"
)

IF(
  AND(
    NOT(ISBLANK({!$Record.dn_Patient_Account__r.dn_Name__c})),

    OR(
      /* If first character is C, it's valid */
      MID(UPPER({!$Record.dn_Patient_Account__r.dn_Name__c}), 1, 1) = "C",

      /* If first character is D, apply second and third character checks */
      AND(
        MID(UPPER({!$Record.dn_Patient_Account__r.dn_Name__c}), 1, 1) = "D",
        MID(UPPER({!$Record.dn_Patient_Account__r.dn_Name__c}), 2, 1) = "A",
        MID(UPPER({!$Record.dn_Patient_Account__r.dn_Name__c}), 3, 1) >= "A",
        MID(UPPER({!$Record.dn_Patient_Account__r.dn_Name__c}), 3, 1) <= "N"
      )
    )
  ),
  "Valid",
  "Invalid"
)

IF(
  AND(
    NOT(ISBLANK({!$Record.dn_Patient_Account__r.dn_Name__c})),

    OR(
      /* First character is D: Valid */
      MID(UPPER({!$Record.dn_Patient_Account__r.dn_Name__c}), 1, 1) = "D",

      /* First character is E: Apply 2nd and 3rd char validations */
      AND(
        MID(UPPER({!$Record.dn_Patient_Account__r.dn_Name__c}), 1, 1) = "E",
        MID(UPPER({!$Record.dn_Patient_Account__r.dn_Name__c}), 2, 1) >= "A",
        MID(UPPER({!$Record.dn_Patient_Account__r.dn_Name__c}), 2, 1) <= "D",
        MID(UPPER({!$Record.dn_Patient_Account__r.dn_Name__c}), 3, 1) >= "A",
        MID(UPPER({!$Record.dn_Patient_Account__r.dn_Name__c}), 3, 1) <= "E"
      )
    )
  ),
  "Valid",
  "Invalid"
)

IF(
  AND(
    NOT(ISBLANK({!$Record.dn_Patient_Account__r.dn_Name__c})),

    OR(
      /* First letter is E or F (no additional checks) */
      MID(UPPER({!$Record.dn_Patient_Account__r.dn_Name__c}), 1, 1) = "E",
      MID(UPPER({!$Record.dn_Patient_Account__r.dn_Name__c}), 1, 1) = "F",

      /* First = G, apply 2nd and 3rd character checks */
      AND(
        MID(UPPER({!$Record.dn_Patient_Account__r.dn_Name__c}), 1, 1) = "G",
        MID(UPPER({!$Record.dn_Patient_Account__r.dn_Name__c}), 2, 1) >= "A",
        MID(UPPER({!$Record.dn_Patient_Account__r.dn_Name__c}), 2, 1) <= "E",
        MID(UPPER({!$Record.dn_Patient_Account__r.dn_Name__c}), 3, 1) >= "A",
        MID(UPPER({!$Record.dn_Patient_Account__r.dn_Name__c}), 3, 1) <= "R"
      )
    )
  ),
  "Valid",
  "Invalid"
)

IF(
  AND(
    NOT(ISBLANK({!$Record.dn_Patient_Account__r.dn_Name__c})),

    OR(
      /* First character is G to I (no extra check) */
      MID(UPPER({!$Record.dn_Patient_Account__r.dn_Name__c}), 1, 1) = "G",
      MID(UPPER({!$Record.dn_Patient_Account__r.dn_Name__c}), 1, 1) = "H",
      MID(UPPER({!$Record.dn_Patient_Account__r.dn_Name__c}), 1, 1) = "I",

      /* First character is J with extra checks */
      AND(
        MID(UPPER({!$Record.dn_Patient_Account__r.dn_Name__c}), 1, 1) = "J",
        MID(UPPER({!$Record.dn_Patient_Account__r.dn_Name__c}), 2, 1) >= "A",
        MID(UPPER({!$Record.dn_Patient_Account__r.dn_Name__c}), 3, 1) >= "A",
        MID(UPPER({!$Record.dn_Patient_Account__r.dn_Name__c}), 3, 1) <= "C"
      )
    )
  ),
  "Valid",
  "Invalid"
)

IF(
  AND(
    NOT(ISBLANK({!$Record.dn_Patient_Account__r.dn_Name__c})),

    /* 1st character must be J */
    MID(UPPER({!$Record.dn_Patient_Account__r.dn_Name__c}), 1, 1) = "J",

    /* 2nd character: J–E */
    MID(UPPER({!$Record.dn_Patient_Account__r.dn_Name__c}), 2, 1) >= "J",
    MID(UPPER({!$Record.dn_Patient_Account__r.dn_Name__c}), 2, 1) <= "E",

    /* 3rd character: J–F */
    MID(UPPER({!$Record.dn_Patient_Account__r.dn_Name__c}), 3, 1) >= "J",
    MID(UPPER({!$Record.dn_Patient_Account__r.dn_Name__c}), 3, 1) <= "F",

    /* 4th character: J–F */
    MID(UPPER({!$Record.dn_Patient_Account__r.dn_Name__c}), 4, 1) >= "J",
    MID(UPPER({!$Record.dn_Patient_Account__r.dn_Name__c}), 4, 1) <= "F",

    /* 5th character: J–R */
    MID(UPPER({!$Record.dn_Patient_Account__r.dn_Name__c}), 5, 1) >= "J",
    MID(UPPER({!$Record.dn_Patient_Account__r.dn_Name__c}), 5, 1) <= "R",

    /* 6th character: J–E */
    MID(UPPER({!$Record.dn_Patient_Account__r.dn_Name__c}), 6, 1) >= "J",
    MID(UPPER({!$Record.dn_Patient_Account__r.dn_Name__c}), 6, 1) <= "E",

    /* 7th character: J–Y */
    MID(UPPER({!$Record.dn_Patient_Account__r.dn_Name__c}), 7, 1) >= "J",
    MID(UPPER({!$Record.dn_Patient_Account__r.dn_Name__c}), 7, 1) <= "Y",

    /* 8th character: must be space */
    MID({!$Record.dn_Patient_Account__r.dn_Name__c}, 8, 1) = " ",

